(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};
  const s = window.__toolboxStore;

  // ① 进元件库 → 自己加一个元件
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库')?.click();
  await sleep(2200);
  out.libraryBefore = (await s.listLibrary()).length;
  document.querySelector('.lib-add')?.click();
  await sleep(900);
  out.editorOpen = !!document.querySelector('.ce-modal');
  out.editorTitle = document.querySelector('.ce-head h2')?.textContent || null;

  // 填表（图片用 canvas 造一张）
  const c = document.createElement('canvas'); c.width = 80; c.height = 60;
  const g = c.getContext('2d'); g.fillStyle = '#2f855a'; g.fillRect(0, 0, 80, 60);
  g.fillStyle = '#fff'; g.font = 'bold 18px sans-serif'; g.fillText('S1', 24, 38);
  const blob = await new Promise((r) => c.toBlob(r, 'image/png'));
  const dt = new DataTransfer();
  dt.items.add(new File([blob], 'sensor.png', { type: 'image/png' }));
  const fileInput = document.querySelector('.ce-figure input[type=file]');
  fileInput.files = dt.files;
  fileInput.dispatchEvent(new Event('change', { bubbles: true }));
  await sleep(1200);
  out.imageNote = document.querySelector('.ce-note')?.textContent || null;
  out.previewOk = (document.querySelector('.ce-figure-box img')?.naturalWidth || 0) > 0;

  const inputs = [...document.querySelectorAll('.ce-fields .ce-input')];
  const byLabel = (label) => {
    const field = [...document.querySelectorAll('.ce-field')].find((f) => f.querySelector('.ce-label')?.textContent.trim().startsWith(label));
    return field?.querySelector('.ce-input');
  };
  setV(byLabel('名字'), '土壤湿度传感器');
  setV(byLabel('它是干嘛的'), '插进土里就知道干不干');
  setV(byLabel('怎么认出来'), '两块金属片 + 一块小电路板');
  setV(byLabel('正负极'), '有方向，VCC 接正极');
  setV(byLabel('怎么读参数'), '看板上丝印 VCC/GND/DO/AO');
  setV(byLabel('常见型号'), 'YL-69、FC-28');
  setV(byLabel('引脚数'), '4');
  setV(byLabel('封装'), '模块');
  setV(byLabel('能做的小项目'), '自动浇水、干湿度报警');
  setV(byLabel('新手常踩'), '探针泡水会腐蚀\n接反了读数乱跳');
  out.fieldsFilled = inputs.length;
  [...document.querySelectorAll('.ce-foot .ce-btn')].find((b) => b.textContent.includes('保存'))?.click();
  await sleep(2000);
  out.editorClosed = !document.querySelector('.ce-modal');
  out.toast = document.querySelector('.lib-toast')?.textContent || null;

  const lib = await s.listLibrary();
  out.libraryAfter = lib.length;
  const mine = lib.filter((x) => x.source !== 'builtin');
  out.mine = mine.map((x) => ({ id: x.id, name: x.name, cat: x.category, purpose: x.purpose, img: !!x.imageUrl, pins: x.pinCount, mistakes: (x.commonMistakes || []).length }));
  out.newId = mine.length ? mine[0].id : null;
  return JSON.stringify(out);
})()
